.foot-version {
  margin: 7px 0 0;
  font-size: 11px;
  line-height: 1.3;
  letter-spacing: 0.02em;
  opacity: 0.72;
}

/* Contabilidad · versión 3: asientos a mano y plan de cuentas de 6 cifras. */

.btn.xs { padding: 3px 7px; font-size: 11.5px; border-radius: 7px; gap: 4px; }
.btn.xs svg { width: 13px; height: 13px; }

.acc-row-tools {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
