 * lee del recibo («Trabajador: …») y, si el recibo no lo trae, del nombre del
 * tercero del documento.
 */
export function claveDeTrabajador(inv) {
  const d = inv || {};
  const nom = d.nomina && typeof d.nomina === "object" ? d.nomina : {};
  const bruto = String(nom.trabajador || d.party || d.supplierName || "").trim();
  const limpio = bruto
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[.,;:]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  return limpio || "";
}

/**
